// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 warpTo) public {
        vm.assume(amount > 0);
        vm.assume(unlockTime < type(uint256).max / 2);
        vm.assume(warpTo > unlockTime && warpTo < type(uint256).max / 2);
        address actor = address(0xA11CE);
        vm.deal(actor, amount);
        vm.warp(warpTo);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint256 ut, ) = c.Acc(actor);
        assertTrue(ut >= block.timestamp);
    }
}
